   106→public(package) fun close_pool_reward<CoinType>(
   107→    pool_reward_manager: &mut PoolRewardManager,
   108→    index: u64,
   109→    clock: &Clock
   110→): Balance<CoinType>{
   111→    let optional_pool_reward = pool_reward_manager.pool_rewards.borrow_mut(index);
   112→    let PoolReward{
   113→        id,
   114→        pool_reward_manager_id: _,
   115→        coin_type: _,
   116→        start_time_ms: _,
   117→        end_time_ms,
   118→        total_rewards: _,
   119→        allocated_rewards: _,
   120→        cumulative_rewards_per_share: _,
   121→        num_obligation_reward_managers,
   122→        mut additional_fields,
   123→    } = optional_pool_reward.extract();
   124→
   125→    object::delete(id);
   126→
   127→    let cur_time_ms = clock.timestamp_ms();
   128→
   129→    assert!(cur_time_ms >= end_time_ms, error::liquidity_mining_pool_reward_period_not_over());
   130→    assert!(num_obligation_reward_managers == 0, error::liquidity_mining_not_all_rewards_claimed());
   131→
   132→    let reward_balance = additional_fields.remove<RewardBalance<CoinType>, Balance<CoinType>>(RewardBalance<CoinType>{});
   133→    additional_fields.destroy_empty();
   134→    
   135→    reward_balance
   136→}   
