#[test]
fun test_pool_reward_manager_basic() {
    use sui::test_scenario::{Self};

    let owner = @0x26;
    let mut scenario = test_scenario::begin(owner);

    let ctx = test_scenario::ctx(&mut scenario);
    let mut clock = clock::create_for_testing(ctx);
    clock.set_for_testing(0);

    let mut pool_reward_manager = new_pool_reward_manager(ctx);
    let usdc = sui::balance::create_for_testing<USDC>(100 * 1_000_000);

    add_pool_reward(&mut pool_reward_manager, usdc, 0, 20 * MILLISECONDS_IN_DAY, &clock, ctx);

    let obligation_id_1 = object::id_from_address(@0x1);
    new_obligation_reward_manager(&mut pool_reward_manager, obligation_id_1, &clock);

    change_obligation_reward_manager_share(
        &mut pool_reward_manager,
        obligation_id_1,
        100,
        &clock,
    );

    // at this point, obligation 1 has earned 50 dollars
    clock.set_for_testing(5 * MILLISECONDS_IN_DAY);
    {
        let usdc = claim_rewards<USDC>(
            &mut pool_reward_manager,
            obligation_id_1,
            &clock,
            0,
        );
        assert!(usdc.value() == 25 * 1_000_000, 0);
        std::unit_test::destroy(usdc);
    };

    let obligation_id_2 = object::id_from_address(@0x2);
    new_obligation_reward_manager(&mut pool_reward_manager, obligation_id_2, &clock);
    change_obligation_reward_manager_share(
        &mut pool_reward_manager,
        obligation_id_2,
        400,
        &clock,
    );

    clock.set_for_testing(10 * MILLISECONDS_IN_DAY);
    {
        let usdc = claim_rewards<USDC>(
            &mut pool_reward_manager,
            obligation_id_1,
            &clock,
            0,
        );
        assert!(usdc.value() == 5 * 1_000_000, 0);
        std::unit_test::destroy(usdc);
    };
    {
        let usdc = claim_rewards<USDC>(
            &mut pool_reward_manager,
            obligation_id_2,
            &clock,
            0,
        );
        assert!(usdc.value() == 20 * 1_000_000, 0);
        std::unit_test::destroy(usdc);
    };

    change_obligation_reward_manager_share(
        &mut pool_reward_manager,
        obligation_id_1,
        250,
        &clock,
    );

    change_obligation_reward_manager_share(
        &mut pool_reward_manager,
        obligation_id_2,
        250,
        &clock,
    );

    clock.set_for_testing(20 * MILLISECONDS_IN_DAY);
    {
        let usdc = claim_rewards<USDC>(
            &mut pool_reward_manager,
            obligation_id_1,
            &clock,
            0,
        );
        assert!(usdc.value() == 25 * 1_000_000, 0);
        std::unit_test::destroy(usdc);
    };

    {
        let usdc = claim_rewards<USDC>(
            &mut pool_reward_manager,
            obligation_id_2,
            &clock,
            0,
        );
        assert!(usdc.value() == 25 * 1_000_000, 0);
        std::unit_test::destroy(usdc);
    };

    std::unit_test::destroy(clock);
    std::unit_test::destroy(pool_reward_manager);

    test_scenario::end(scenario);
}

