#[test]
fun test_pool_reward_manager_cancel_and_close_regression() {
    use sui::test_scenario::{Self};
    let owner = @0x26;
    let mut scenario = test_scenario::begin(owner);
    let ctx = test_scenario::ctx(&mut scenario);
    let mut clock = clock::create_for_testing(ctx);
    clock.set_for_testing(0);
    let mut pool_reward_manager = new_pool_reward_manager(ctx);
    let usdc = sui::balance::create_for_testing<USDC>(100 * 1_000_000);
    add_pool_reward(&mut pool_reward_manager, usdc, 0, 20 * MILLISECONDS_IN_DAY, &clock, ctx);
    let usdc = sui::balance::create_for_testing<USDC>(100 * 1_000_000);
    add_pool_reward(
        &mut pool_reward_manager,
        usdc,
        20 * MILLISECONDS_IN_DAY,
        30 * MILLISECONDS_IN_DAY,
        &clock,
        ctx,
    );
    let obligation_id_1 = object::id_from_address(@0x1);
    new_obligation_reward_manager(&mut pool_reward_manager, obligation_id_1, &clock);
    change_obligation_reward_manager_share(
        &mut pool_reward_manager,
        obligation_id_1,
        100,
        &clock,
    );
    clock.set_for_testing(10 * MILLISECONDS_IN_DAY);
    let unallocated_rewards = cancel_pool_reward<USDC>(&mut pool_reward_manager, 0, &clock);
    assert!(unallocated_rewards.value() == 50 * 1_000_000, 0);
    clock.set_for_testing(15 * MILLISECONDS_IN_DAY);
    let obligation_rewards = claim_rewards<USDC>(
        &mut pool_reward_manager,
        obligation_id_1,
        &clock,
        0,
    );
    assert!(obligation_rewards.value() == 50 * 1_000_000, 0);
    let dust_rewards = close_pool_reward<USDC>(&mut pool_reward_manager, 0, &clock);
    assert!(dust_rewards.value() == 0, 0);
    clock.set_for_testing(20 * MILLISECONDS_IN_DAY);
    let obligation_id_2 = object::id_from_address(@0x2);
    new_obligation_reward_manager(&mut pool_reward_manager, obligation_id_2, &clock);
    change_obligation_reward_manager_share(
        &mut pool_reward_manager,
        obligation_id_2,
        100,
        &clock,
    );
    clock.set_for_testing(30 * MILLISECONDS_IN_DAY);
    let obligation_rewards_2 = claim_rewards<USDC>(
        &mut pool_reward_manager,
        obligation_id_2,
        &clock,
        1,
    );

    assert!(obligation_rewards_2.value() == 50 * 1_000_000, 0);
    std::unit_test::destroy(unallocated_rewards);
    std::unit_test::destroy(obligation_rewards);
    std::unit_test::destroy(obligation_rewards_2);
    std::unit_test::destroy(dust_rewards);
    std::unit_test::destroy(clock);
    std::unit_test::destroy(pool_reward_manager);
    test_scenario::end(scenario);
}

